/**
 * Typed access to the paper's Agentic Benchmark Checklist assessment (the
 * appendix table with one mark per checklist item and benchmark).
 * The JSON is generated by scripts/export_paper.py from the paper source;
 * the totals are recomputed from the marks and checked against the totals the
 * paper prints under the table.
 */
import data from '../data/paper/abc.json';
import explanations from '../data/abc-explanations.json';
import definitions from '../data/abc-definitions.json';

export type AbcMark = 'yes' | 'no' | 'na';
export type AbcCategoryId = 'outcome' | 'task' | 'reporting';

export interface AbcBenchmark {
  /** Column abbreviation used in the paper's table, for example "MV". */
  id: string;
  name: string;
  ours: boolean;
}
export interface AbcItem {
  /** Checklist item id, for example "O.a.1". */
  id: string;
  /** The paper's abridged statement of the requirement. */
  requirement: string;
  marks: Record<string, AbcMark>;
  /** Note markers attached to single cells, keyed by benchmark id. */
  noteMarks: Record<string, string>;
}
export interface AbcCategory {
  id: AbcCategoryId;
  title: string;
  items: AbcItem[];
}
export interface AbcTotal {
  satisfied: number;
  notSatisfied: number;
  notApplicable: number;
  applicable: number;
}
export interface AbcNote {
  marker: string | null;
  text: string;
}

/**
 * The order of the benchmarks on this page, in the bars and in the table
 * alike: MultiVerse, GAIA2, AppWorld, AutomationBench, HANDBOOK.md,
 * Toolathlon, so that the bars read from the most satisfied items at the top
 * to the fewest at the bottom. The order is written here, not computed: if
 * the marks change, check that it still runs that way. The exported JSON
 * keeps the order of the paper's table, and a benchmark missing from this
 * list follows the listed ones in that order.
 */
const COLUMN_ORDER = ['MV', 'G2', 'AW', 'AB', 'HB', 'TA'];
const columnPosition = (id: string) => {
  const index = COLUMN_ORDER.indexOf(id);
  return index === -1 ? COLUMN_ORDER.length : index;
};

export const ABC_CHECKLIST = data.checklist;
export const ABC_BENCHMARKS = [...(data.benchmarks as AbcBenchmark[])].sort((a, b) => columnPosition(a.id) - columnPosition(b.id));
export const ABC_CATEGORIES = data.categories as AbcCategory[];
export const ABC_ITEMS = ABC_CATEGORIES.flatMap(category => category.items);

/** Authored from the assessment notes, separate from the generated paper marks. */
export const ABC_EXPLANATIONS: Record<string, Record<string, string>> = explanations;

/** Original checklist definitions transcribed from the user-supplied ABC v5 PDF. */
export const ABC_DEFINITION_SOURCE = definitions.source;
export const ABC_DEFINITIONS: Record<string, { definition: string; page: number; figure: number; sourceId: string; verbatim?: boolean }> = definitions.items;

/** Counts of the three marks over a list of items, for one benchmark. */
export function abcTotal(items: readonly AbcItem[], benchmark: string): AbcTotal {
  const count = (mark: AbcMark) => items.filter(item => item.marks[benchmark] === mark).length;
  const notApplicable = count('na');
  return { satisfied: count('yes'), notSatisfied: count('no'), notApplicable, applicable: items.length - notApplicable };
}
/** Totals over all items, per benchmark id. They follow the marks as this page shows them. */
export const ABC_TOTALS: Record<string, AbcTotal> = Object.fromEntries(ABC_BENCHMARKS.map(benchmark => [benchmark.id, abcTotal(ABC_ITEMS, benchmark.id)]));

/** The paper's table notes. */
export const ABC_NOTES = data.notes as AbcNote[];

/** This work's column. */
export const ABC_OURS = ABC_BENCHMARKS.find(benchmark => benchmark.ours) ?? ABC_BENCHMARKS[0];

/** Satisfied items: the numerator of the paper's total. */
export const abcScore = (total: AbcTotal) => total.satisfied;
